/**
 * @fileoverview Test the usage of a removed Class
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-removed-class-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester({
    settings: {
        extjs: {
            toolkit: 'modern',
            fromVersion: '6.0',
            toVersion: '7.9.0'
        }
    }
});
ruleTester.run('no-removed-class-usage', rule, {

    valid: [

    ],

    invalid: [
        {
            code: `
                Ext.define('Oreilly.view.Location', {
                    extend: 'Ext.Container',
                    requires: 'Ext.BingMap',
                    initialize: function () {
                        var map;

                        this.callParent();

                        map = this.add({
                            xtype: 'bingmap',
                            mapOptions: {
                                center: position,
                                mapTypeId: Microsoft.Maps.MapTypeId.ROADMAP,
                                callback: mapCallback
                            }
                        });
                    }
                });
            `,
            errors: [
                { message: /Usage of removed Class 'Ext.BingMap' found./ }
            ]
        }
    ]
});
